@import url('https://spoqa.github.io/spoqa-han-sans/css/SpoqaHanSansNeo.css');
:root { --slk-splash-logo-url: none; }
/* =====================================================
   Slack UI for SillyTavern — v0.9.2
   Mobile · Light — header + bottom tab bar
   (PC 화면은 기존 스타일 유지)
   ===================================================== */



/* ---------- 디자인 토큰 (라이트) ---------- */
body.slk-ui {
    --slk-aubergine: #4A154B;
    --slk-aubergine-deep: #3F0E40;
    --slk-header-grad: #441848;
    --slk-header-fg: #FFFFFF;
    --slk-pill-bg: #4F1756;
    --slk-pill-border: #9B3BA4;

    --slk-surface: #FFFFFF;
    --slk-active: #1264A3;
    --slk-text: #1D1C1D;
    --slk-muted: #616061;
    --slk-border: #E3E3E3;
    --slk-tab-active-bg: #EFEAF0;
    --slk-tab-active-fg: #4A154B;
    --slk-shadow: 0 6px 24px rgba(0, 0, 0, 0.10), 0 1px 3px rgba(0, 0, 0, 0.06);

    --slk-font: 'Spoqa Han Sans Neo', 'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif;
    font-family: var(--slk-font) !important;

    --slk-header-h: 60px;
    --slk-tabbar-h: 60px;
    --slk-tabbar-gap: 10px;
    --slk-safe-top: env(safe-area-inset-top, 0px);
    --slk-safe-bottom: env(safe-area-inset-bottom, 0px);
    --slk-footer-h: calc(var(--slk-tabbar-h) + var(--slk-tabbar-gap) * 2 + var(--slk-safe-bottom));
    --slk-top-h: calc(var(--slk-header-h) + var(--slk-safe-top));
}

/* PC에서는 아직 숨김 (다음 단계에서 작업) */
#slk-header,
#slk-settings-menu {
    display: none;
}

@media screen {

    /* ===================================================
       1) 헤더
       =================================================== */

    /* ST 원래 상단 바 배경은 숨기고 헤더로 대체 */
    body.slk-ui #top-bar {
        display: none !important;
    }

    /* 헤더 높이를 ST 상단 기준값으로 지정 → 채팅창, 패널 위치가 자동으로 맞춰짐 */
    body.slk-ui {
        --topBarBlockSize: var(--slk-top-h) !important;
    }

    #slk-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        position: fixed;
        inset: 0 0 auto 0;
        height: var(--slk-top-h);
        padding: var(--slk-safe-top) 14px 0 12px;
        box-sizing: border-box;
        background: var(--slk-header-grad);
        color: var(--slk-header-fg);
        font-family: var(--slk-font);
        z-index: 3010;
    }

    #slk-header button {
        all: unset;
        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
    }

    /* 왼쪽: 현재 캐릭터 = 워크스페이스 */
    #slk-header #slk-ws {
        display: flex;
        align-items: center;
        gap: 10px;
        min-width: 0;
        max-width: 70vw;
    }

    .slk-ws-avatar {
        position: relative;
        flex: 0 0 auto;
        width: 44px;
        height: 44px;
        border-radius: 50%;
        padding: 5px;
        box-sizing: border-box;
        border: 1.5px solid var(--slk-pill-border);
        background: var(--slk-pill-bg);
        display: grid;
        place-items: center;
    }

    .slk-ws-avatar {
        overflow: hidden;
    }

    .slk-ws-avatar img {
        display: none;
        width: 100%;
        height: 100%;
        border-radius: 50%;
        object-fit: cover;
    }

    .slk-ws-avatar.has-img img {
        display: block;
    }

    .slk-ws-initial {
        width: 100%;
        height: 100%;
        border-radius: 50%;
        background: #FFFFFF;
        color: var(--slk-aubergine);
        font-weight: 900;
        font-size: 14px;
        display: grid;
        place-items: center;
    }

    .slk-ws-avatar.has-img .slk-ws-initial {
        display: none;
    }

    /* 보라색 전체 헤더: 프로필 이미지를 강제로 정사각형 중앙 크롭 후 정원으로 표시.
       스크롤 후의 원형(컴팩트) 헤더는 기존 스타일 그대로 둡니다. */
    body.slk-ui:not(.slk-header-compact) #slk-header .slk-ws-avatar {
        flex: 0 0 44px !important;
        width: 44px !important;
        min-width: 44px !important;
        max-width: 44px !important;
        height: 44px !important;
        min-height: 44px !important;
        max-height: 44px !important;
        aspect-ratio: 1 / 1;
        overflow: hidden;
        border-radius: 50% !important;
        box-sizing: border-box;
    }

    body.slk-ui:not(.slk-header-compact) #slk-header .slk-ws-avatar > img {
        position: absolute;
        inset: 4px auto auto 4px;
        display: block;
        width: 34px !important;
        min-width: 34px !important;
        max-width: 34px !important;
        height: 34px !important;
        min-height: 34px !important;
        max-height: 34px !important;
        aspect-ratio: 1 / 1;
        object-fit: cover !important;
        object-position: 50% 50% !important;
        border-radius: 50% !important;
    }

    body.slk-ui:not(.slk-header-compact) #slk-header .slk-ws-avatar:not(.has-img) > img {
        display: none;
    }

    /* SillyTavern 1.19.0 staging — 한 줄 */
    .slk-ws-text {
        display: flex;
        align-items: baseline;
        gap: 7px;
        min-width: 0;
        white-space: nowrap;
        overflow: hidden;
    }

    .slk-ws-name {
        font-size: 19px;
        font-weight: 900;
        letter-spacing: -0.01em;
    }

    .slk-ws-ver,
    .slk-ws-branch {
        font-size: 13px;
        font-weight: 700;
        color: rgba(255, 255, 255, 0.72);
    }

    .slk-ws-branch[hidden] {
        display: none;
    }

    /* 오른쪽: 설정 pill */
    .slk-header-actions {
        display: flex;
        align-items: center;
        height: 44px;
        padding: 0 4px;
        box-sizing: border-box;
        border-radius: 22px;
        background: var(--slk-pill-bg);
        border: 1.5px solid var(--slk-pill-border);
    }

    #slk-header #slk-settings-btn {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: grid;
        place-items: center;
        font-size: 18px;
        color: var(--slk-header-fg);
        transition: background 0.15s;
    }

    #slk-header #slk-settings-btn.slk-active,
    body.slk-ui:has(#user-settings-button .drawer-icon.openIcon) #slk-settings-btn,
    body.slk-ui:has(#backgrounds-button .drawer-icon.openIcon) #slk-settings-btn {
        background: rgba(255, 255, 255, 0.20);
    }

    /* 설정 드롭다운 */
    #slk-settings-menu {
        display: block;
        position: fixed;
        top: calc(var(--slk-top-h) + 6px);
        right: 12px;
        min-width: 190px;
        padding: 6px;
        background: var(--slk-surface);
        border: 1px solid var(--slk-border);
        border-radius: 12px;
        box-shadow: var(--slk-shadow);
        font-family: var(--slk-font);
        z-index: 3020;
    }

    #slk-settings-menu[hidden] {
        display: none;
    }

    .slk-menu-item {
        all: unset;
        display: flex;
        align-items: center;
        gap: 12px;
        width: 100%;
        box-sizing: border-box;
        padding: 12px 12px;
        border-radius: 8px;
        font-size: 15px;
        color: var(--slk-text);
        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
    }

    .slk-menu-icon {
        flex: 0 0 24px;
        display: grid;
        place-items: center;
        color: var(--slk-muted);
    }

    .slk-menu-item:active,
    .slk-menu-item:hover {
        background: #F4F4F4;
    }

    /* ===================================================
       2) 바텀 탭바 (원래 상단 탭바를 아래로)
       =================================================== */

    body.slk-ui #top-settings-holder {
        position: fixed !important;
        top: auto !important;
        left: 12px !important;
        right: 12px !important;
        bottom: calc(var(--slk-tabbar-gap) + var(--slk-safe-bottom)) !important;
        width: auto !important;
        height: var(--slk-tabbar-h) !important;
        margin: 0 !important;
        padding: 0 6px !important;
        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;
        justify-content: space-between !important;
        background: var(--slk-surface) !important;
        border: 1px solid var(--slk-border) !important;
        border-radius: calc(var(--slk-tabbar-h) / 2) !important;
        box-shadow: var(--slk-shadow) !important;
        /* 패널(position: fixed)이 탭바 기준으로 갇히지 않도록 */
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        filter: none !important;
        transform: none !important;
        z-index: 3000 !important;
    }

    /* 탭바 아래쪽 흰색 페이드 (슬랙처럼 떠 있는 느낌) */
    body.slk-ui::after {
        content: '';
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        height: var(--slk-footer-h);
        background: linear-gradient(to bottom, rgba(255, 255, 255, 0) 0%, var(--slk-surface) 45%);
        pointer-events: none;
        z-index: 2999;
    }

    /* 탭 순서: 프롬프트 / 연결 / 고급서식 / 로어북 / 확장 / 페르소나 / 캐릭터 */
    body.slk-ui #ai-config-button { order: 1; }
    body.slk-ui #sys-settings-button { order: 2; }
    body.slk-ui #advanced-formatting-button { order: 3; }
    body.slk-ui #WI-SP-button { order: 4; }
    body.slk-ui #extensions-settings-button { order: 5; }
    body.slk-ui #persona-management-button { order: 6; }
    body.slk-ui #rightNavHolder { order: 7; }

    /* 사용자 설정, 배경은 탭바에서 숨기고 헤더 설정 메뉴로 이동
       (드로어 패널 자체는 살려둬야 하므로 버튼만 숨김) */
    body.slk-ui #user-settings-button,
    body.slk-ui #backgrounds-button {
        order: 99;
        flex: 0 0 0 !important;
        width: 0 !important;
        min-width: 0 !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    body.slk-ui #user-settings-button > .drawer-toggle,
    body.slk-ui #backgrounds-button > .drawer-toggle {
        display: none !important;
    }

    /* 각 탭 */
    body.slk-ui #top-settings-holder > .drawer {
        flex: 1 1 0;
        display: flex;
        justify-content: center;
        align-items: center;
        margin: 0 !important;
        padding: 0 !important;
    }

    body.slk-ui #top-settings-holder > .drawer > .drawer-toggle {
        display: grid;
        place-items: center;
        width: 44px;
        height: 44px;
        border-radius: 14px;
        transition: background 0.15s;
        -webkit-tap-highlight-color: transparent;
    }

    /* 테마 원래 아이콘은 숨기고 (열림 상태 감지용으로 DOM에는 남김) 슬랙 라인 아이콘 표시 */
    body.slk-ui #top-settings-holder > .drawer > .drawer-toggle > .drawer-icon {
        display: none !important;
    }

    body.slk-ui .slk-tab-icon {
        display: grid;
        place-items: center;
        color: var(--slk-muted);
        transition: color 0.15s;
    }

    /* 활성 탭 = 연보라 배경 + 아베진 아이콘 (조금 더 굵게) */
    body.slk-ui #top-settings-holder > .drawer:has(.drawer-icon.openIcon) > .drawer-toggle {
        background: var(--slk-tab-active-bg);
    }

    body.slk-ui #top-settings-holder > .drawer:has(.drawer-icon.openIcon) .slk-tab-icon {
        color: var(--slk-tab-active-fg);
    }

    body.slk-ui #top-settings-holder > .drawer:has(.drawer-icon.openIcon) .slk-tab-icon svg {
        stroke-width: 2.3;
    }

    /* ===================================================
       3) 채팅창, 패널 높이를 헤더와 탭바 사이에 맞추기
       =================================================== */

    body.slk-ui #sheld {
        top: var(--slk-top-h) !important;
        height: calc(100dvh - var(--slk-top-h) - var(--slk-footer-h)) !important;
        max-height: calc(100dvh - var(--slk-top-h) - var(--slk-footer-h)) !important;
    }

    body.slk-ui .drawer-content,
    body.slk-ui #left-nav-panel,
    body.slk-ui #right-nav-panel {
        top: var(--slk-top-h) !important;
        height: calc(100dvh - var(--slk-top-h) - var(--slk-footer-h)) !important;
        max-height: calc(100dvh - var(--slk-top-h) - var(--slk-footer-h)) !important;
    }

    /* 채팅 영역 바탕: 테마 테두리, 블러 제거 */
    body.slk-ui #sheld,
    body.slk-ui #chat {
        background: var(--slk-surface) !important;
        border: none !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
    }

    body.slk-ui #chat {
        padding: 0 !important;
    }

    /* ===================================================
       4) 최근 채팅 (welcomePanel) — 슬랙 홈 스타일
       구성 항목은 그대로, 디자인만 변경
       =================================================== */

    /* 폰트어썸 아이콘 → 슬랙 라인 아이콘 (마스크) */
    body.slk-ui .welcomePanel .fa-circle-chevron-down, body.slk-ui .welcomePanel .fa-gear, body.slk-ui .welcomePanel .fa-circle-xmark, body.slk-ui .welcomePanel .fa-question-circle, body.slk-ui .welcomePanel .fa-github, body.slk-ui .welcomePanel .fa-discord, body.slk-ui .welcomePanel .fa-comment-dots, body.slk-ui .welcomePanel .fa-thumbtack, body.slk-ui .welcomePanel .fa-pen-to-square, body.slk-ui .welcomePanel .fa-trash, body.slk-ui .welcomePanel .fa-comment, body.slk-ui .welcomePanel .fa-chevron-down {
        display: inline-block !important;
        width: 18px !important;
        height: 18px !important;
        background-color: currentColor !important;
        -webkit-mask: var(--slk-ico) center / contain no-repeat;
        mask: var(--slk-ico) center / contain no-repeat;
        font-size: 0 !important;
        vertical-align: middle;
    }

    body.slk-ui .welcomePanel .fa-circle-chevron-down::before, body.slk-ui .welcomePanel .fa-gear::before, body.slk-ui .welcomePanel .fa-circle-xmark::before, body.slk-ui .welcomePanel .fa-question-circle::before, body.slk-ui .welcomePanel .fa-github::before, body.slk-ui .welcomePanel .fa-discord::before, body.slk-ui .welcomePanel .fa-comment-dots::before, body.slk-ui .welcomePanel .fa-thumbtack::before, body.slk-ui .welcomePanel .fa-pen-to-square::before, body.slk-ui .welcomePanel .fa-trash::before, body.slk-ui .welcomePanel .fa-comment::before, body.slk-ui .welcomePanel .fa-chevron-down::before {
        content: none !important;
    }

