    /* ---------- 패널 바탕: 테마 박스, 그림자 제거 ---------- */
    body.slk-ui .welcomePanel {
        background: var(--slk-surface) !important;
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        padding: 0 0 12px !important;
        margin: 0 !important;
        gap: 0 !important;
        font-family: var(--slk-font);
        color: var(--slk-text);
    }

    /* 패널 안 버튼은 전부 테마 스타일 초기화 */
    body.slk-ui .welcomePanel .menu_button,
    body.slk-ui .welcomePanel .mes_button {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
        filter: none !important;
        text-shadow: none !important;
        outline: none !important;
        margin: 0 !important;
        padding: 0 !important;
        min-width: 0 !important;
        min-height: 0 !important;
        color: var(--slk-muted) !important;
        opacity: 1 !important;
        -webkit-tap-highlight-color: transparent;
    }

    /* ---------- 레이아웃: 패널을 그리드로 재배치 ----------
       1줄: 바로가기 아이콘
       2줄: Recent Chats 제목 | 펼치기 · 목록 설정 · 닫기
       3줄: 채팅 목록
       (로고, 버전은 헤더와 중복이라 숨김) */
    body.slk-ui .welcomePanel {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) auto auto auto;
        align-items: center;
    }

    body.slk-ui .welcomePanel .welcomeHeaderTitle,
    body.slk-ui .welcomePanel .welcomeHeader {
        display: contents !important;
    }

    body.slk-ui .welcomePanel .welcomeHeaderLogo,
    body.slk-ui .welcomePanel .welcomeHeaderVersionDisplay {
        display: none !important;
    }

    body.slk-ui .welcomePanel .welcomeShortcuts {
        grid-column: 1 / -1;
        grid-row: 1;
    }

    body.slk-ui .welcomePanel .recentChatsTitle {
        grid-column: 1;
        grid-row: 2;
    }

    body.slk-ui .welcomePanel .showRecentChats { grid-column: 2; grid-row: 2; }
    body.slk-ui .welcomePanel .recentChatsSettings { grid-column: 3; grid-row: 2; }
    body.slk-ui .welcomePanel .hideRecentChats { grid-column: 4; grid-row: 2; margin-right: 8px !important; }

    body.slk-ui .welcomePanel .welcomeRecent {
        grid-column: 1 / -1;
        grid-row: 3;
    }

    body.slk-ui .welcomePanel .welcomeHeaderTitle .mes_button {
        display: grid;
        place-items: center;
        width: 36px !important;
        height: 36px !important;
        margin-top: 10px !important;
        border-radius: 8px !important;
    }

    body.slk-ui .welcomePanel .welcomeHeaderTitle .mes_button:active {
        background: #F1F1F1 !important;
    }

    /* 접힌 상태(recentHidden)에서도 ST 원래 동작 유지 */
    body.slk-ui .welcomePanel.recentHidden .hideRecentChats,
    body.slk-ui .welcomePanel.recentHidden .recentChatsSettings,
    body.slk-ui .welcomePanel:not(.recentHidden) .showRecentChats {
        display: none !important;
    }

    /* ---------- 바로가기 = 슬랙 홈 상단 카드 (화면 폭에 4개 딱 맞게) ---------- */
    body.slk-ui .welcomePanel .welcomeShortcuts {
        flex-wrap: nowrap !important;
        justify-content: stretch !important;
        gap: 8px !important;
        padding: 14px 16px !important;
        overflow: visible !important;
        border-bottom: 1px solid var(--slk-border);
    }

    body.slk-ui .welcomePanel .welcomeShortcuts .welcomeShortcutsSeparator {
        display: none !important;
    }

    body.slk-ui .welcomePanel .welcomeShortcuts .menu_button {
        flex: 1 1 0 !important;
        min-width: 0 !important;
        display: flex !important;
        flex-direction: column !important;
        align-items: flex-start !important;
        justify-content: space-between !important;
        gap: 10px !important;
        height: 84px !important;
        padding: 12px 10px 10px 12px !important;
        box-sizing: border-box;
        border: 1px solid var(--slk-border) !important;
        border-radius: 12px !important;
        background: var(--slk-surface) !important;
        color: var(--slk-text) !important;
        text-align: left !important;
        text-decoration: none !important;
    }

    body.slk-ui .welcomePanel .welcomeShortcuts .menu_button:active {
        background: #F8F8F8 !important;
    }

    body.slk-ui .welcomePanel .welcomeShortcuts .menu_button i {
        width: 22px !important;
        height: 22px !important;
        flex: 0 0 auto;
    }

    /* ST가 모바일에서 숨기는 영문 라벨을 다시 표시 */
    body.slk-ui .welcomePanel .welcomeShortcuts .menu_button span {
        display: block !important;
        width: 100%;
        font-size: 13px;
        font-weight: 400;
        line-height: 1.2;
        color: var(--slk-text);
        text-align: left;
        white-space: normal;
        overflow-wrap: normal;
    }

    /* ---------- 3행: '최근 채팅' 섹션 제목 ---------- */
    body.slk-ui .welcomePanel .recentChatsTitle {
        display: flex;
        align-items: center;
        gap: 10px;
        padding: 18px 16px 6px;
        font-size: 16px !important;
        font-weight: 900 !important;
        color: var(--slk-text);
    }

    /* ---------- 채팅 목록 = 슬랙 DM 목록 ---------- */
    body.slk-ui .welcomeRecent .recentChatList {
        gap: 0 !important;
    }

    body.slk-ui .welcomeRecent .recentChatList .recentChat {
        align-items: flex-start !important;
        gap: 12px !important;
        padding: 12px 12px 12px 16px !important;
        border: none !important;
        border-radius: 0 !important;
        background: transparent !important;
        /* 목록 구분선 (옅은 회색) */
        box-shadow: inset 0 -1px 0 #EBEBEB !important;
    }

    body.slk-ui .welcomeRecent .recentChatList .recentChat:has(+ .showMoreChats),
    body.slk-ui .welcomeRecent .recentChatList .recentChat:last-child {
        box-shadow: none !important;
    }

    body.slk-ui .welcomeRecent .recentChatList .recentChat:active {
        background: #F8F8F8 !important;
    }

    /* 아바타: 둥근 사각형 40px */
    body.slk-ui .welcomeRecent .recentChat .avatar {
        flex: 0 0 40px !important;
        width: 40px !important;
        height: 40px !important;
        align-self: flex-start !important;
        margin-top: 2px;
    }

    body.slk-ui .welcomeRecent .recentChat .avatar img {
        width: 40px !important;
        height: 40px !important;
        border-radius: 8px !important;
        border: none !important;
        box-shadow: none !important;
        object-fit: cover;
    }

    /* 고정된 채팅 = 아바타 모서리에 핀 배지 */
    body.slk-ui .welcomeRecent .recentChat .recentChatPinned {
        top: 4px !important;
        left: 40px !important;
        width: 18px;
        height: 18px;
        border-radius: 50%;
        display: grid;
        place-items: center;
        background: var(--slk-aubergine);
        color: #FFFFFF !important;
        border: 2px solid #FFFFFF;
        opacity: 1 !important;
        z-index: 1;
    }

    body.slk-ui .welcomeRecent .recentChat .recentChatPinned i {
        width: 10px !important;
        height: 10px !important;
    }

    /* 정보 영역 = 3줄 그리드
       1줄: 이름 – 채팅명 | 날짜
       2줄: 메시지 미리보기
       3줄: 메시지 수 · 용량 | 고정 / 이름변경 / 삭제 */
    body.slk-ui .welcomeRecent .recentChat .recentChatInfo {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) auto;
        column-gap: 8px;
        row-gap: 2px;
        align-self: stretch !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatNameContainer,
    body.slk-ui .welcomeRecent .recentChat .chatMessageContainer {
        display: contents !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatName {
        grid-column: 1;
        grid-row: 1;
        font-size: 15px;
        line-height: 1.35;
        color: var(--slk-muted);
    }

    body.slk-ui .welcomeRecent .recentChat .chatName .characterName {
        font-weight: 600;
        color: var(--slk-text);
    }

    body.slk-ui .welcomeRecent .recentChat .chatDate {
        grid-column: 2;
        grid-row: 1;
        align-self: center;
        justify-self: end;
        text-align: right;
        margin-right: 8px; /* 휴지통 아이콘 오른쪽 끝에 맞춤 */
        font-size: 12px;
        color: var(--slk-muted);
        white-space: nowrap;
    }

    body.slk-ui .welcomeRecent .recentChat .chatMessage {
        grid-column: 1 / -1;
        grid-row: 2;
        font-size: 14px;
        line-height: 1.4;
        color: var(--slk-muted);
    }

    body.slk-ui .welcomeRecent .recentChat .chatStats {
        grid-column: 1;
        grid-row: 3;
        align-self: center !important;
        justify-content: flex-start !important;
        align-items: center !important;
        gap: 6px !important;
        font-size: 12px;
        line-height: 1 !important;
        color: #868686;
    }

    body.slk-ui .welcomeRecent .recentChat .chatStats .counterBlock {
        align-items: center !important;
        gap: 4px !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatStats .counterBlock i {
        width: 13px !important;
        height: 13px !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatStats .counterBlock::after {
        content: '·' !important;
        color: #B5B5B5 !important;
        margin-left: 2px;
    }

    /* 액션 버튼 = 아이콘만 있는 고스트 버튼 */
    body.slk-ui .welcomeRecent .recentChat .chatActions {
        grid-column: 2;
        grid-row: 3;
        gap: 2px !important;
        justify-content: flex-end !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatActions .menu_button {
        display: grid !important;
        place-items: center;
        width: 32px !important;
        height: 30px !important;
        border-radius: 6px !important;
        font-size: inherit !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatActions .menu_button i {
        width: 16px !important;
        height: 16px !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatActions .menu_button:active {
        background: #EDEDED !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatActions .pinChat.active {
        color: var(--slk-aubergine) !important;
        background: var(--slk-tab-active-bg) !important;
    }

    body.slk-ui .welcomeRecent .recentChat .chatActions .deleteChat:active {
        color: #E01E5A !important;
    }

    /* 더 보기 */
    body.slk-ui .welcomeRecent .recentChatList .showMoreChats {
        align-self: stretch !important;
        display: grid !important;
        place-items: center;
        height: 40px !important;
        margin: 4px 16px 0 !important;
        border-radius: 8px !important;
    }

    body.slk-ui .welcomeRecent .recentChatList .showMoreChats:active {
        background: #F4F4F4 !important;
    }

    /* 최근 채팅 없음 */
    body.slk-ui .welcomePanel .recentChatList .noRecentChat {
        color: var(--slk-muted);
        padding: 24px 16px !important;
        align-items: center !important;
    }

    /* ===================================================
       5) 팝업 — 슬랙 모달 스타일
       (최근 채팅 설정: 제목 + 입력 2개 + 저장/취소)
       =================================================== */
    body.slk-ui .popup {
        width: calc(100vw - 32px) !important;
        max-width: 440px !important;
        padding: 0 !important;
        background: var(--slk-surface) !important;
        color: var(--slk-text) !important;
        border: none !important;
        border-radius: 14px !important;
        box-shadow: 0 18px 48px rgba(0, 0, 0, 0.22), 0 2px 6px rgba(0, 0, 0, 0.08) !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        font-family: var(--slk-font);
        text-align: left !important;
    }

    body.slk-ui .popup[open]::backdrop {
        background: rgba(29, 28, 29, 0.45) !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
    }

    body.slk-ui .popup .popup-body {
        padding: 0 !important;
    }

    /* 헤더 */
    body.slk-ui .popup .popup-content {
        margin: 0 !important;
        padding: 20px 20px 4px !important;
        text-align: left !important;
    }

    body.slk-ui .popup .popup-content h3,
    body.slk-ui .popup .popup-header {
        margin: 0 !important;
        font-size: 19px !important;
        font-weight: 900 !important;
        color: var(--slk-text) !important;
        text-align: left !important;
    }

    /* 입력 필드 */
    body.slk-ui .popup .popup-inputs {
        padding: 8px 20px 0 !important;
    }

    body.slk-ui .popup .popup-inputs .text_label {
        display: flex !important;
        flex-direction: column !important;
        align-items: stretch !important;
        justify-content: flex-start !important;
        gap: 6px !important;
        margin: 0 0 14px !important;
        text-align: left !important;
    }

    body.slk-ui .popup .popup-inputs .text_label > span {
        font-size: 15px;
        font-weight: 700;
        color: var(--slk-text);
        opacity: 1 !important;
    }

    body.slk-ui .popup .text_pole {
        width: 100% !important;
        height: 44px;
        margin: 0 !important;
        padding: 0 12px !important;
        box-sizing: border-box;
        background: var(--slk-surface) !important;
        color: var(--slk-text) !important;
        font-family: var(--slk-font);
        font-size: 16px !important;
        border: 1px solid #BBBBBB !important;
        border-radius: 8px !important;
        box-shadow: none !important;
        outline: none !important;
    }

    body.slk-ui .popup textarea.text_pole {
        height: auto;
        padding: 10px 12px !important;
    }

    body.slk-ui .popup .text_pole:focus {
        border-color: var(--slk-active) !important;
        box-shadow: 0 0 0 3px rgba(17, 100, 163, 0.25) !important;
    }

    /* 버튼: 오른쪽 정렬, 취소(흰색) → 저장(초록) */
    body.slk-ui .popup .popup-controls {
        align-self: stretch !important;
        justify-content: flex-end !important;
        gap: 8px !important;
        margin: 8px 0 0 !important;
        padding: 14px 20px 18px !important;
        border-top: 1px solid var(--slk-border);
