    /* ===================================================
       8) 고급 서식 패널 — 슬랙 설정 화면 스타일
       =================================================== */
    body.slk-ui #AdvancedFormatting {
        background: var(--slk-surface) !important;
        color: var(--slk-text) !important;
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        padding: 16px 16px 28px !important;
        font-family: var(--slk-font);
        overflow-y: auto !important;
        overflow-x: hidden !important;
        min-width: 0 !important;
        max-width: 100vw !important;
        box-sizing: border-box;
    }

    body.slk-ui #AdvancedFormatting * {
        max-width: 100%;
        box-sizing: border-box;
    }

    /* 테마가 붙인 세로 막대, 그림자 제거 */
    body.slk-ui #AdvancedFormatting h3,
    body.slk-ui #AdvancedFormatting h4,
    body.slk-ui #AdvancedFormatting label,
    body.slk-ui #AdvancedFormatting .flex-container,
    body.slk-ui #AdvancedFormatting .flex1 {
        border: none !important;
        box-shadow: none !important;
        background-color: transparent;
    }

    body.slk-ui #AdvancedFormatting h3::before,
    body.slk-ui #AdvancedFormatting h4::before {
        display: none !important;
    }

    /* ---------- 맨 위: 제목 + 마스터 불러오기/내보내기 ---------- */
    body.slk-ui #AdvancedFormatting > .flex-container:first-child {
        display: flex !important;
        flex-direction: column !important;
        align-items: stretch !important;
        gap: 12px !important;
        margin: 0 0 12px !important;
    }

    body.slk-ui #AdvancedFormatting > .flex-container:first-child h3,
    body.slk-ui #AdvancedFormatting > .flex-container:first-child h3 span {
        margin: 0 !important;
        padding: 0 !important;
        align-items: center !important;
        gap: 6px;
        font-size: 19px !important;
        font-weight: 900 !important;
        color: var(--slk-text) !important;
    }

    body.slk-ui #AdvancedFormatting > .flex-container:first-child > .flex-container {
        display: flex !important;
        flex-wrap: nowrap !important;
        gap: 8px !important;
    }

    body.slk-ui #AdvancedFormatting #af_master_import,
    body.slk-ui #AdvancedFormatting #af_master_export {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        margin: 0 !important;
        flex: 1 1 0;
        height: 40px !important;
        padding: 0 12px !important;
        gap: 8px !important;
        border: none !important;
        border-radius: 999px !important;
        background: #F1F1F1 !important;
        color: var(--slk-text) !important;
        box-shadow: none !important;
        filter: none !important;
        text-shadow: none !important;
        font-size: 14px !important;
        font-weight: 700 !important;
    }

    /* Chat Completion 안내 = 연노랑 알림 */
    body.slk-ui #AdvancedFormatting #advanced-formatting-cc-notice {
        align-items: flex-start;
        gap: 10px;
        margin: 0 0 8px !important;
        padding: 10px 12px !important;
        border: none !important;
        border-radius: 8px !important;
        background: #FFF6D6 !important;
        color: #5C4A00 !important;
        font-size: 13px !important;
        line-height: 1.45;
        box-shadow: none !important;
    }

    body.slk-ui #AdvancedFormatting #advanced-formatting-cc-notice * {
        color: inherit !important;
    }

    body.slk-ui #AdvancedFormatting #advanced-formatting-cc-notice i {
        flex: 0 0 auto;
        margin-top: 1px;
    }

    /* 세 열(컨텍스트 / 지시 / 시스템 프롬프트)을 모바일에선 위아래로 쌓기 */
    body.slk-ui #AdvancedFormatting > .flex-container.spaceEvenly {
        display: flex !important;
        flex-direction: column !important;
        flex-wrap: nowrap !important;
        gap: 0 !important;
    }

    body.slk-ui #AdvancedFormatting > .flex-container.spaceEvenly > div {
        flex: 0 0 auto !important;
        width: 100% !important;
        min-width: 0 !important;
    }

    /* ---------- 섹션 제목 (컨텍스트 템플릿, 지시 템플릿, 시스템 프롬프트, 토크나이저, Reasoning, 기타 …) ---------- */
    body.slk-ui #AdvancedFormatting h4.standoutHeader,
    body.slk-ui #AdvancedFormatting h4.standoutHeader b,
    body.slk-ui #AdvancedFormatting h4.standoutHeader span {
        font-size: 16px !important;
        font-weight: 900 !important;
        color: var(--slk-text) !important;
    }

    body.slk-ui #AdvancedFormatting h4.standoutHeader {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 8px;
        min-height: 36px;
        margin: 24px 0 10px !important;
        padding: 20px 0 0 !important;
        border-top: 1px solid var(--slk-border) !important;
    }

    body.slk-ui #AdvancedFormatting h4.standoutHeader > div {
        display: flex !important;
        align-items: center;
        gap: 6px !important;
    }

    /* ---------- 헤더 토글 (자동 감지 ⚡ / 컨텍스트 연결 🔗 / 켜기 ⏻) = 원형 버튼 ---------- */
    body.slk-ui #AdvancedFormatting h4 .checkbox_label {
        flex: 0 0 auto !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    body.slk-ui #AdvancedFormatting h4 .checkbox_label small {
        display: contents;
    }

    body.slk-ui #AdvancedFormatting h4 .checkbox_label .menu_button {
        display: inline-grid !important;
        place-items: center;
        width: 34px !important;
        min-width: 34px !important;
        height: 34px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        border-radius: 999px !important;
        background: #F1F1F1 !important;
        color: #9A9A9A !important;
        box-shadow: none !important;
        filter: none !important;
        font-size: 0 !important;
        opacity: 1 !important;
    }

    body.slk-ui #AdvancedFormatting h4 .checkbox_label .menu_button.toggleEnabled {
        background: var(--slk-tab-active-bg) !important;
        color: var(--slk-aubergine) !important;
    }

    /* 켜기(⏻): 켜짐 = 초록, 꺼짐 = 회색 */
    body.slk-ui #AdvancedFormatting h4 .checkbox_label .fa-power-off.toggleEnabled {
        background: #E7F4EE !important;
        color: #007A5A !important;
    }

    /* ---------- 템플릿 선택 줄: [선택 ▾] (저장·이름변경·새로·복원·삭제 = 연회색 알약) ---------- */
    body.slk-ui #AdvancedFormatting .flex-container:has(> select[data-preset-manager-for]) {
        display: flex !important;
        flex-wrap: nowrap !important;
        align-items: center !important;
        gap: 8px !important;
        margin: 0 0 4px !important;
    }

    body.slk-ui #AdvancedFormatting .flex-container:has(> select[data-preset-manager-for]) > select {
        flex: 1 1 0 !important;
        min-width: 0 !important;
        width: 0 !important;
    }

    body.slk-ui #AdvancedFormatting .flex-container:has(> select[data-preset-manager-for]) > .flex-container {
        flex: 0 0 auto;
        display: flex !important;
        flex-wrap: nowrap !important;
        gap: 0 !important;
        margin: 0 !important;
        padding: 3px !important;
        border-radius: 999px !important;
        background: #F1F1F1 !important;
    }

    body.slk-ui #AdvancedFormatting .flex-container:has(> select[data-preset-manager-for]) > .flex-container .menu_button {
        display: inline-grid !important;
        place-items: center;
        width: 32px !important;
        min-width: 32px !important;
        height: 36px !important;
        margin: 0 !important;
        padding: 0 !important;
