    /* ===================================================
       13) 채팅창 — 슬랙 메시지 목록 + 입력창
       =================================================== */
    body.slk-ui #chat {
        background: var(--slk-surface) !important;
        padding: 6px 0 calc(var(--slk-footer-h) + var(--slk-form-h, 0px) + 12px) !important;
        max-height: none !important;
        font-family: var(--slk-font);
        overflow-x: hidden !important;
    }

    /* ---------- 메시지 한 개: [아바타] 이름 · 시간 ··· / 본문 / 스와이프 ---------- */
    body.slk-ui #chat .mes {
        display: grid !important;
        grid-template-columns: 40px minmax(0, 1fr) auto auto;
        grid-template-rows: auto auto;
        column-gap: 10px;
        row-gap: 0;
        align-items: start;
        width: 100% !important;
        margin: 0 !important;
        padding: 10px 16px 10px !important;
        border: none !important;
        border-radius: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        color: var(--slk-text) !important;
        box-sizing: border-box;
    }

    body.slk-ui #chat .mes * {
        box-sizing: border-box;
    }

    body.slk-ui #chat .mes.selected {
        background: #FDECF2 !important;
    }

    body.slk-ui #chat .mes .for_checkbox {
        display: none !important;
    }

    body.slk-ui #chat .mes .del_checkbox {
        position: absolute;
        top: 12px;
        right: 16px;
        z-index: 2;
    }

    body.slk-ui #chat .mesAvatarWrapper {
        grid-column: 1;
        grid-row: 1 / span 2;
        display: flex !important;
        flex-direction: column !important;
        align-items: center !important;
        gap: 3px !important;
        width: 40px !important;
        min-width: 40px !important;
        margin: 2px 0 0 !important;
        padding: 0 !important;
    }

    body.slk-ui #chat .mesAvatarWrapper .avatar,
    body.slk-ui #chat .mesAvatarWrapper .avatar img {
        width: 40px !important;
        height: 40px !important;
        min-width: 40px !important;
        margin: 0 !important;
        border: none !important;
        border-radius: 8px !important;
        box-shadow: none !important;
        outline: none !important;
        object-fit: cover;
    }

    /* #번호 · 걸린 시간 · 토큰 = 아바타 밑에 작게 */
    body.slk-ui #chat .mesIDDisplay,
    body.slk-ui #chat .mes_timer,
    body.slk-ui #chat .tokenCounterDisplay {
        margin: 0 !important;
        padding: 0 !important;
        font-family: var(--slk-font) !important;
        font-size: 11px !important;
        font-weight: 400 !important;
        font-style: normal !important;
        line-height: 1.2 !important;
        color: #8A8A8A !important;
        opacity: 1 !important;
        text-align: center;
        white-space: nowrap;
    }

    body.slk-ui #chat .mes_block {
        grid-column: 2 / -1;
        grid-row: 1;
        min-width: 0 !important;
        width: auto !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        background: transparent !important;
        box-shadow: none !important;
        overflow: visible !important;
    }

    body.slk-ui #chat .ch_name {
        display: flex !important;
        flex-wrap: nowrap !important;
        align-items: center !important;
        gap: 4px !important;
        min-height: 24px;
        margin: 0 0 2px !important;
        padding: 0 !important;
        border: none !important;
        background: transparent !important;
    }

    body.slk-ui #chat .ch_name > .flex-container:first-child {
        flex: 1 1 auto !important;
        min-width: 48px !important;
        margin: 0 !important;
    }

    body.slk-ui #chat .ch_name .alignItemsBaseline {
        display: flex !important;
        flex-wrap: nowrap !important;
        align-items: baseline !important;
        gap: 6px !important;
        min-width: 0;
    }

    body.slk-ui #chat .name_text {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        font-family: var(--slk-font) !important;
        font-size: 15px !important;
        font-weight: 600 !important;
        color: var(--slk-text) !important;
        text-shadow: none !important;
    }

    body.slk-ui #chat .timestamp {
        flex: 0 0 auto;
        margin: 0 !important;
        font-family: var(--slk-font) !important;
        font-size: 12px !important;
        color: #8A8A8A !important;
        opacity: 1 !important;
        white-space: nowrap;
    }

    body.slk-ui #chat .mes_ghost {
        align-self: center;
        color: #8A8A8A !important;
        font-size: 0 !important;
    }

    body.slk-ui #chat .mes_ghost::before {
        width: 14px !important;
        height: 14px !important;
    }

    /* ··· · ✎ = 이름 줄 오른쪽 작은 회색 버튼 */
    body.slk-ui #chat .mes_buttons {
        flex: 0 1 auto;
        min-width: 0;
        position: relative;
        flex-wrap: nowrap !important;
        gap: 0 !important;
        align-items: center !important;
        height: 30px;
        margin: -3px -8px -3px 0 !important;
        padding: 0 !important;
        overflow: visible !important;
        font-size: 0 !important;
    }

    body.slk-ui #chat .mes_buttons .mes_button:not(.slk-foreign-action),
    body.slk-ui #chat .extraMesButtons > div:not(.slk-foreign-action) {
        width: 32px !important;
        height: 30px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        border-radius: 6px !important;
        background: transparent !important;
        color: #8A8A8A !important;
        box-shadow: none !important;
        filter: none !important;
        opacity: 1 !important;
        font-size: 0 !important;
        line-height: 30px !important;
        text-align: center;
    }

    body.slk-ui #chat .mes_buttons .mes_button::before,
    body.slk-ui #chat .extraMesButtons > div::before {
        width: 17px !important;
        height: 17px !important;
    }

    body.slk-ui #chat .mes_buttons .mes_button:active {
        background: #F1F1F1 !important;
    }

    /* ··· 누르면 나오는 추가 버튼 = 편집 버튼처럼 이름 줄에 한 줄로 (넘치면 옆으로 밀어서 보기) */
    body.slk-ui #chat .extraMesButtons {
        position: static !important;
        flex: 0 1 auto;
        flex-wrap: nowrap !important;
        justify-content: flex-end !important;
        gap: 2px !important;
        min-width: 0;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        border-radius: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
        overflow-x: auto !important;
        overflow-y: hidden !important;
        scrollbar-width: none;
    }

    body.slk-ui #chat .extraMesButtons::-webkit-scrollbar {
        display: none;
    }

    body.slk-ui #chat .extraMesButtons > div {
        flex: 0 0 32px;
        color: #6B6B6B !important;
    }

    body.slk-ui #chat .extraMesButtons > div:active {
        background: #F1F1F1 !important;
    }

    /* 편집 중 버튼: ✓ 초록 / 나머지 회색 / 삭제 빨강 */
    body.slk-ui #chat .mes_edit_buttons {
        flex: 0 0 auto;
        float: none !important;
        flex-wrap: nowrap !important;
        align-items: center !important;
        gap: 2px !important;
        height: 30px;
        margin: -3px -4px -3px 0 !important;
        padding: 0 !important;
        filter: none !important;
    }

    body.slk-ui #chat .mes_edit_buttons .menu_button {
        width: 32px !important;
        height: 30px !important;
        min-width: 0 !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        border-radius: 6px !important;
        background: transparent !important;
        color: #6B6B6B !important;
        box-shadow: none !important;
        filter: none !important;
