    /* ===================================================
       14) 글라스: 채팅이 헤더 · 입력창 · 탭바 밑으로 흐르고, 그 위에 반투명 유리
       =================================================== */
    body.slk-ui {
        --slk-glass-bg: rgba(255, 255, 255, 0.48);
        --slk-glass-border: rgba(255, 255, 255, 0.75);
        --slk-glass-shadow: 0 8px 28px rgba(0, 0, 0, 0.12), 0 1px 3px rgba(0, 0, 0, 0.06), inset 0 1px 0 rgba(255, 255, 255, 0.9);
        --slk-glass-blur: blur(20px) saturate(180%);
    }

    /* 채팅 영역을 화면 맨 아래까지 (탭바 · 입력창은 그 위에 떠 있음) */
    body.slk-ui #sheld {
        height: calc(100dvh - var(--slk-top-h)) !important;
        max-height: calc(100dvh - var(--slk-top-h)) !important;
    }

    body.slk-ui #form_sheld {
        position: absolute !important;
        left: 0 !important;
        right: 0 !important;
        bottom: calc(var(--slk-footer-h) - 4px) !important;
        width: 100% !important;
        background: transparent !important;
        z-index: 40 !important;
    }

    /* 바텀 탭바: 유리 (패널 위치가 탭바에 갇히지 않게 탭바 자체가 아니라 ::before에 블러) */
    body.slk-ui #top-settings-holder {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    body.slk-ui #top-settings-holder::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 5;
        border: 1px solid var(--slk-glass-border);
        border-radius: inherit;
        background: var(--slk-glass-bg);
        box-shadow: var(--slk-glass-shadow);
        backdrop-filter: var(--slk-glass-blur);
        -webkit-backdrop-filter: var(--slk-glass-blur);
        pointer-events: none;
    }

    /* 탭바 안에서 쌓는 순서: 패널(1) < 유리 바탕(5) < 탭 버튼(6) */
    body.slk-ui #top-settings-holder .drawer-content,
    body.slk-ui #top-settings-holder #left-nav-panel,
    body.slk-ui #top-settings-holder #right-nav-panel {
        z-index: 1 !important;
    }

    body.slk-ui #top-settings-holder > .drawer > .drawer-toggle {
        position: relative;
        z-index: 6;
    }

    body.slk-ui #top-settings-holder > .drawer:has(.drawer-icon.openIcon) > .drawer-toggle {
        background: rgba(74, 21, 75, 0.10) !important;
    }

    body.slk-ui::after {
        display: none !important;
    }

    /* 패널도 화면 맨 아래까지 → 탭바(유리) 밑으로 패널 내용이 흐름. 마지막 내용은 탭바 위까지 스크롤됨 */
    body.slk-ui #left-nav-panel,
    body.slk-ui #rm_api_block,
    body.slk-ui #AdvancedFormatting,
    body.slk-ui #WorldInfo,
    body.slk-ui #user-settings-block,
    body.slk-ui #Backgrounds,
    body.slk-ui #rm_extensions_block,
    body.slk-ui #PersonaManagement,
    body.slk-ui #right-nav-panel {
        height: calc(100dvh - var(--slk-top-h)) !important;
        max-height: calc(100dvh - var(--slk-top-h)) !important;
    }

    body.slk-ui #rm_api_block,
    body.slk-ui #AdvancedFormatting,
    body.slk-ui #WorldInfo,
    body.slk-ui #user-settings-block,
    body.slk-ui #Backgrounds,
    body.slk-ui #rm_extensions_block,
    body.slk-ui #PersonaManagement,
    body.slk-ui #left-nav-panel .scrollableInner,
    body.slk-ui #right-nav-panel .scrollableInner {
        padding-bottom: calc(var(--slk-footer-h) + 20px) !important;
    }

    /* 입력창: 유리 */
    body.slk-ui #form_sheld #send_form {
        border-color: rgba(0, 0, 0, 0.08) !important;
        background: rgba(250, 250, 250, 0.28) !important;
        box-shadow: 0 6px 22px rgba(0, 0, 0, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: var(--slk-glass-blur) !important;
        -webkit-backdrop-filter: var(--slk-glass-blur) !important;
    }

    body.slk-ui #form_sheld #send_form.slk-compose-open {
        border-color: rgba(255, 255, 255, 0.75) !important;
        background: rgba(255, 255, 255, 0.26) !important;
        box-shadow: 0 8px 28px rgba(0, 0, 0, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.9) !important;
    }

    /* 입력 중에는 바텀 탭바를 숨기고 입력창을 맨 아래로 */
    body.slk-ui.slk-composing #top-settings-holder::before,
    body.slk-ui.slk-composing #top-settings-holder > .drawer > .drawer-toggle {
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
    }

    /* 키보드가 아래 안전 영역을 덮으므로 여백 없이 바로 붙임 */
    body.slk-ui.slk-composing #sheld {
        padding-bottom: 0 !important;
    }

    body.slk-ui.slk-composing #form_sheld {
        bottom: 0 !important;
        padding-bottom: 6px !important;
    }

    body.slk-ui.slk-composing #chat {
        padding-bottom: calc(var(--slk-form-h, 0px) + 12px) !important;
    }

    /* ===================================================
       15) 채팅방 헤더: ‹ 뒤로 / (프사 · 이름 · 💬 메시지 수)
       =================================================== */
    #slk-chat-head {
        display: none;
    }

    body.slk-ui.slk-in-chat #sheld {
        top: 0 !important;
        height: 100dvh !important;
        max-height: 100dvh !important;
    }

    body.slk-ui.slk-in-chat #chat {
        padding-top: calc(var(--slk-top-h) + 4px) !important;
    }

    body.slk-ui.slk-in-chat #slk-header {
        background: linear-gradient(to bottom, rgba(255, 255, 255, 0.92) 0%, rgba(255, 255, 255, 0.6) 55%, rgba(255, 255, 255, 0) 100%);
        color: var(--slk-text);
    }

    body.slk-ui.slk-in-chat:has(.drawer-content.openDrawer) #slk-header {
        background: var(--slk-surface);
    }

    body.slk-ui.slk-in-chat #slk-header > #slk-ws,
    body.slk-ui.slk-in-chat #slk-header > .slk-header-actions {
        display: none !important;
    }

    body.slk-ui.slk-in-chat #slk-chat-head {
        display: flex;
        align-items: center;
        gap: 8px;
        width: 100%;
        min-width: 0;
    }

    #slk-chat-back,
    #slk-chat-title {
        border: 1px solid var(--slk-glass-border) !important;
        background: var(--slk-glass-bg) !important;
        box-shadow: 0 4px 16px rgba(0, 0, 0, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: var(--slk-glass-blur) !important;
        -webkit-backdrop-filter: var(--slk-glass-blur) !important;
        color: var(--slk-text) !important;
        cursor: pointer;
    }

    #slk-header #slk-chat-back {
        flex: 0 0 46px;
        display: grid;
        place-items: center;
        width: 46px;
        height: 46px;
        border-radius: 50%;
        box-sizing: border-box;
    }

    #slk-header #slk-chat-title {
        flex: 0 1 auto;
        display: flex;
        align-items: center;
        gap: 10px;
        min-width: 0;
        height: 46px;
        padding: 0 18px 0 5px;
        border-radius: 23px;
        box-sizing: border-box;
    }

    #slk-chat-title .slk-ch-av {
        flex: 0 0 36px;
        width: 36px;
        height: 36px;
        border-radius: 50%;
        object-fit: cover;
        background: #E8E8E8;
    }

    #slk-chat-title .slk-ch-av[hidden] {
        display: none;
    }

    #slk-chat-title .slk-ch-text {
        display: flex;
        flex-direction: column;
        min-width: 0;
        line-height: 1.15;
    }

    #slk-chat-title .slk-ch-name {
