    }

    /* ‹ 뒤로 + 로고는 왼쪽에 붙여서 */
    body.slk-ui #slk-header #slk-ws {
        margin-right: auto;
    }

    /* ‹ 뒤로 버튼이 생기면 로고·글자가 그만큼 오른쪽으로 (한 줄 유지) */
    body.slk-ui:not(.slk-header-compact):has(#user-settings-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#backgrounds-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#ai-config-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#sys-settings-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#advanced-formatting-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#WI-SP-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#extensions-settings-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#persona-management-button .drawer-icon.openIcon) #slk-header #slk-ws,
    body.slk-ui:not(.slk-header-compact):has(#rightNavHolder .drawer-icon.openIcon) #slk-header #slk-ws {
        flex: 1 1 auto;
