    /* ===================================================
       17) 사용자 설정 — 탭 (테마 / 캐릭터 / 기타 / 채팅) + 설정 목록
       =================================================== */
    body.slk-ui #user-settings-block {
        background: var(--slk-surface) !important;
        color: var(--slk-text) !important;
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        padding-top: 16px !important;
        padding-left: 16px !important;
        padding-right: 16px !important;
        font-family: var(--slk-font);
        overflow-y: auto !important;
        overflow-x: hidden !important;
        min-width: 0 !important;
        max-width: 100vw !important;
        box-sizing: border-box;
    }

    body.slk-ui #user-settings-block * {
        box-sizing: border-box;
        max-width: 100%;
    }

    body.slk-ui #user-settings-block h3::before,
    body.slk-ui #user-settings-block h4::before {
        display: none !important;
    }

    body.slk-ui #user-settings-block hr {
        display: none !important;
    }

    /* ---------- 맨 위: 제목 · 버전 / UI 언어 / [계정] [검색] ---------- */
    body.slk-ui #user-settings-block > .flex-container:first-child {
        display: flex !important;
        flex-direction: column !important;
        gap: 12px !important;
        margin: 0 0 6px !important;
    }

    body.slk-ui #user-settings-block [name="userSettingsRowOne"] {
        display: flex !important;
        flex-wrap: wrap !important;
        align-items: center !important;
        gap: 4px 10px !important;
        margin: 0 !important;
    }

    body.slk-ui #user-settings-block [name="userSettingsRowOne"] > .flex-container:first-child {
        flex: 1 1 auto;
        min-width: 0;
    }

    body.slk-ui #user-settings-block h3 {
        display: flex !important;
        align-items: center !important;
        gap: 6px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        font-size: 19px !important;
        font-weight: 900 !important;
        color: var(--slk-text) !important;
    }

    body.slk-ui #user-settings-block #version_display {
        flex: 0 0 auto;
        order: 2;
        font-size: 12px !important;
        color: var(--slk-muted) !important;
        opacity: 1 !important;
        text-align: right;
    }

    body.slk-ui #user-settings-block #UI-language-block {
        order: 3;
        flex: 0 0 100%;
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 12px !important;
        margin: 6px 0 0 !important;
        padding: 6px 0 !important;
        border-bottom: 1px solid #EFEFEF;
    }

    body.slk-ui #user-settings-block #UI-language-block > span {
        font-size: 15px !important;
        color: var(--slk-text) !important;
    }

    body.slk-ui #user-settings-block #ui_language_select {
        flex: 0 0 52% !important;
        width: 52% !important;
    }

    body.slk-ui #user-settings-block [name="UserSettingsRowTwo"] {
        display: flex !important;
        flex-wrap: nowrap !important;
        align-items: center !important;
        gap: 8px !important;
        margin: 0 !important;
    }

    body.slk-ui #user-settings-block #account_controls {
        flex: 0 0 auto;
        display: flex !important;
        gap: 6px !important;
        margin: 0 !important;
    }

    body.slk-ui #user-settings-block #settingsSearch {
        flex: 1 1 auto !important;
        min-width: 0 !important;
        height: 42px !important;
        min-height: 42px !important;
        padding: 10px 12px 10px 36px !important;
        resize: none !important;
        overflow: hidden !important;
        line-height: 20px !important;
        background: var(--slk-surface) url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23616061%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2211%22%20cy%3D%2211%22%20r%3D%227%22%2F%3E%3Cpath%20d%3D%22m20%2020-3.5-3.5%22%2F%3E%3C%2Fsvg%3E") 11px center / 17px no-repeat !important;
    }

    /* ---------- 탭 바 (프롬프트 탭과 같은 모양) ---------- */
    #slk-ustabs {
        display: none;
    }

    body.slk-ui #slk-ustabs {
        position: sticky;
        top: -16px;
        z-index: 4;
        display: flex;
        width: calc(100% + 32px) !important;
        max-width: none !important;
        margin: 0 -16px 4px;
        padding: 0 8px;
        background: var(--slk-surface);
        border-bottom: 1px solid var(--slk-border);
    }

    body.slk-ui #user-settings-block[data-slk-active-tab="theme"]:not([data-slk-searching="1"]) [data-slk-tab]:not([data-slk-tab="theme"]),
    body.slk-ui #user-settings-block[data-slk-active-tab="char"]:not([data-slk-searching="1"]) [data-slk-tab]:not([data-slk-tab="char"]),
    body.slk-ui #user-settings-block[data-slk-active-tab="misc"]:not([data-slk-searching="1"]) [data-slk-tab]:not([data-slk-tab="misc"]),
    body.slk-ui #user-settings-block[data-slk-active-tab="chat"]:not([data-slk-searching="1"]) [data-slk-tab]:not([data-slk-tab="chat"]) {
        display: none !important;
    }

    body.slk-ui #user-settings-block[data-slk-searching="1"] #slk-ustabs {
        display: none;
    }

    /* 세 칸 → 한 줄로 */
    body.slk-ui #user-settings-block #user-settings-block-content,
    body.slk-ui #user-settings-block #UI-Theme-Block,
    body.slk-ui #user-settings-block #UI-Customization,
    body.slk-ui #user-settings-block #power-user-options-block,
    body.slk-ui #user-settings-block #power-user-option-checkboxes,
    body.slk-ui #user-settings-block [name="themeElements"] {
        display: flex;
        flex-direction: column !important;
        flex-wrap: nowrap !important;
        gap: 0 !important;
        width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
    }

    /* ---------- 섹션 제목 ---------- */
    body.slk-ui #user-settings-block h4 {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 8px !important;
        margin: 18px 0 6px !important;
        padding: 0 !important;
        border: none !important;
        font-size: 16px !important;
        font-weight: 900 !important;
        color: var(--slk-text) !important;
    }

    body.slk-ui #user-settings-block [data-slk-tab] > h4:first-child,
    body.slk-ui #user-settings-block [data-slk-tab] > div:first-child > h4:first-child,
    body.slk-ui #user-settings-block #UI-presets-block > h4 {
        margin-top: 12px !important;
    }

    /* UI 테마: 제목 옆 [가져오기·내보내기·삭제] 회색 알약, 선택칸 옆 [저장·새로 저장] 회색 알약 */
    body.slk-ui #user-settings-block #UI-presets-block {
        gap: 8px !important;
        margin: 0 0 6px !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block h4 > .flex-container,
    body.slk-ui #user-settings-block #UI-presets-block > .flex-container {
        flex-wrap: nowrap !important;
        gap: 0 !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block > .flex-container {
        gap: 8px !important;
    }

    body.slk-ui #user-settings-block #themes {
        flex: 1 1 auto !important;
        min-width: 0 !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block .menu_button {
        display: grid !important;
        place-items: center;
        width: 40px !important;
        min-width: 40px !important;
        height: 38px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        border-radius: 0 !important;
        background: #F1F1F1 !important;
        color: var(--slk-text) !important;
        box-shadow: none !important;
        filter: none !important;
        font-size: 0 !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block .menu_button:first-child {
        border-radius: 999px 0 0 999px !important;
        padding-left: 4px !important;
        width: 44px !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block .menu_button:last-child {
        border-radius: 0 999px 999px 0 !important;
        padding-right: 4px !important;
        width: 44px !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block #themes + .menu_button {
        border-radius: 999px 0 0 999px !important;
        padding-left: 4px !important;
        width: 44px !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block #ui-preset-save-button {
        margin-left: -8px !important;
    }

    body.slk-ui #user-settings-block #ui-preset-delete-button {
        color: #E01E5A !important;
    }

    body.slk-ui #user-settings-block #UI-presets-block .menu_button i::before {
        width: 17px !important;
        height: 17px !important;
    }

    /* ---------- 이름 | 선택칸 줄 ---------- */
    body.slk-ui #user-settings-block [name="AvatarAndChatDisplay"] {
        gap: 0 !important;
    }

    body.slk-ui #user-settings-block [name="AvatarAndChatDisplay"] > div,
    body.slk-ui #user-settings-block [name="CharacterHandlingToggles"] > .flex-container,
    body.slk-ui #user-settings-block #examples-behavior-block,
    body.slk-ui #user-settings-block #examples-behavior-block + div,
    body.slk-ui #user-settings-block [name="ChatMessageHandlingToggles"] > .flex-container.alignitemscenter,
    body.slk-ui #user-settings-block #MovingUI-presets-block {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) minmax(0, 52%);
        align-items: center !important;
        gap: 12px !important;
        min-height: 54px;
        margin: 0 !important;
        padding: 6px 0 !important;
        border-bottom: 1px solid #EFEFEF;
    }

    body.slk-ui #user-settings-block [name="AvatarAndChatDisplay"] > div > *,
    body.slk-ui #user-settings-block [name="CharacterHandlingToggles"] > .flex-container > *,
    body.slk-ui #user-settings-block #examples-behavior-block > *,
    body.slk-ui #user-settings-block #examples-behavior-block + div > *,
    body.slk-ui #user-settings-block [name="ChatMessageHandlingToggles"] > .flex-container.alignitemscenter > * {
        align-self: center !important;
        margin: 0 !important;
    }

    body.slk-ui #user-settings-block [name="AvatarAndChatDisplay"] > div > span,
    body.slk-ui #user-settings-block [name="CharacterHandlingToggles"] > .flex-container small,
    body.slk-ui #user-settings-block #examples-behavior-block small,
    body.slk-ui #user-settings-block #examples-behavior-block + div small,
    body.slk-ui #user-settings-block [name="ChatMessageHandlingToggles"] > .flex-container.alignitemscenter > small {
        font-size: 15px !important;
        line-height: 1.35 !important;
        color: var(--slk-text) !important;
        opacity: 1 !important;
    }

    body.slk-ui #user-settings-block [name="AvatarAndChatDisplay"] select,
