    html body.slk-ui #WorldInfo #WIMultiSelector .select2-selection__choice {
        display: inline-flex !important;
        align-items: center !important;
        gap: 4px !important;
        height: 30px !important;
        margin: 0 !important;
        padding: 0 10px 0 6px !important;
        border: none !important;
