   왼쪽 색 아이콘(정보·성공·경고·오류) + 굵은 제목 + 본문 + 닫기
   ===================================================================== */
@media screen {
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > div,
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast {
        position: relative !important;
        box-sizing: border-box !important;
        width: 100% !important;
        min-width: 0 !important;
        max-width: 100% !important;
        min-height: 0 !important;
        margin: 0 0 8px !important;
        padding: 12px 40px 12px 48px !important;
        border: 0 !important;
        border-left: 0 !important;
        border-radius: 12px !important;
        background: rgba(29, 28, 29, .94) !important;
        background-image: none !important;
        -webkit-backdrop-filter: blur(16px) saturate(160%) !important;
        backdrop-filter: blur(16px) saturate(160%) !important;
        color: #FFFFFF !important;
        box-shadow: 0 8px 24px rgba(0, 0, 0, .22) !important;
        text-shadow: none !important;
        text-align: left !important;
        filter: none !important;
        overflow: hidden !important;
        cursor: default !important;
    }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > div:hover {
        box-shadow: 0 8px 24px rgba(0, 0, 0, .22) !important;
    }

    /* 왼쪽 아이콘 동그라미 */
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > div::before {
        content: '' !important;
        position: absolute !important;
        left: 14px !important;
        top: 12px !important;
        width: 22px !important;
        height: 22px !important;
        border-radius: 50% !important;
        background: #1D9BD1 !important;
    }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > div::after {
        content: '' !important;
        position: absolute !important;
        left: 18px !important;
        top: 16px !important;
        width: 14px !important;
        height: 14px !important;
        background-color: #FFFFFF !important;
        -webkit-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M12%2011v7%22/%3E%3Cpath%20d%3D%22M12%206.5h.01%22/%3E%3C/svg%3E") center / contain no-repeat !important;
        mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M12%2011v7%22/%3E%3Cpath%20d%3D%22M12%206.5h.01%22/%3E%3C/svg%3E") center / contain no-repeat !important;
        border: 0 !important;
    }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast-success::before { background: #2BAC76 !important; }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast-success::after { -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M20%206%209%2017l-5-5%22/%3E%3C/svg%3E") !important; mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M20%206%209%2017l-5-5%22/%3E%3C/svg%3E") !important; }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast-warning::before { background: #ECB22E !important; }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast-warning::after { -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M12%209v4%22/%3E%3Cpath%20d%3D%22M12%2017h.01%22/%3E%3Cpath%20d%3D%22M10.3%203.9%201.8%2018a2%202%200%200%200%201.7%203h17a2%202%200%200%200%201.7-3L13.7%203.9a2%202%200%200%200-3.4%200z%22/%3E%3C/svg%3E") !important; mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M12%209v4%22/%3E%3Cpath%20d%3D%22M12%2017h.01%22/%3E%3Cpath%20d%3D%22M10.3%203.9%201.8%2018a2%202%200%200%200%201.7%203h17a2%202%200%200%200%201.7-3L13.7%203.9a2%202%200%200%200-3.4%200z%22/%3E%3C/svg%3E") !important; background-color: #1D1C1D !important; }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast-error::before { background: #E01E5A !important; }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > .toast-error::after { -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M18%206%206%2018%22/%3E%3Cpath%20d%3D%22m6%206%2012%2012%22/%3E%3C/svg%3E") !important; mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M18%206%206%2018%22/%3E%3Cpath%20d%3D%22m6%206%2012%2012%22/%3E%3C/svg%3E") !important; }

    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-title {
        display: block !important;
        margin: 0 0 2px !important;
        padding: 0 !important;
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
        font: 700 14px/20px var(--slk-font, sans-serif) !important;
        letter-spacing: -0.01em !important;
        text-align: left !important;
        text-shadow: none !important;
    }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-message {
        display: block !important;
        margin: 0 !important;
        padding: 0 !important;
        color: rgba(255, 255, 255, .82) !important;
        -webkit-text-fill-color: rgba(255, 255, 255, .82) !important;
        font: 400 13px/19px var(--slk-font, sans-serif) !important;
        letter-spacing: -0.01em !important;
        text-align: left !important;
        text-shadow: none !important;
        overflow-wrap: anywhere !important;
    }
    /* 제목 없이 본문만 있을 때는 본문을 흰색 굵게 */
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container > div:not(:has(.toast-title)) .toast-message {
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
        font-weight: 600 !important;
        font-size: 14px !important;
        line-height: 20px !important;
        padding-top: 1px !important;
    }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-message a,
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-message label {
        color: #FFFFFF !important;
        text-decoration: underline !important;
    }

    /* 닫기 버튼 */
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-close-button {
        position: absolute !important;
        top: 10px !important;
        right: 10px !important;
        float: none !important;
        display: block !important;
        width: 24px !important;
        height: 24px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 6px !important;
        background: transparent !important;
        font-size: 0 !important;
        color: transparent !important;
        text-shadow: none !important;
        box-shadow: none !important;
        opacity: 1 !important;
    }
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-close-button::before {
        content: '' !important;
        position: absolute !important;
        inset: 5px !important;
        background-color: rgba(255, 255, 255, .6) !important;
        -webkit-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M18%206%206%2018%22/%3E%3Cpath%20d%3D%22m6%206%2012%2012%22/%3E%3C/svg%3E") center / contain no-repeat !important;
        mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M18%206%206%2018%22/%3E%3Cpath%20d%3D%22m6%206%2012%2012%22/%3E%3C/svg%3E") center / contain no-repeat !important;
    }

    /* 진행 막대: 아래 얇은 선 */
    html:has(> body.slk-ui):not(#slk-a):not(#slk-b):not(#slk-c) #toast-container .toast-progress {
        position: absolute !important;
        left: 0 !important;
        bottom: 0 !important;
        height: 3px !important;
        border-radius: 0 !important;
        background: rgba(255, 255, 255, .35) !important;
        opacity: 1 !important;
    }
    
}

/* 1.4.46: 확장이 직접 띄우는 진행 알림(번역 중 등) = 알림 카드와 같은 모양 */
@media screen {
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) .slk-notice {
        border: 0 !important;
        border-radius: 12px !important;
        background: rgba(29, 28, 29, .94) !important;
        background-image: none !important;
        -webkit-backdrop-filter: blur(16px) saturate(160%) !important;
        backdrop-filter: blur(16px) saturate(160%) !important;
        color: #FFFFFF !important;
        box-shadow: 0 8px 24px rgba(0, 0, 0, .22) !important;
        outline: none !important;
        font-family: var(--slk-font, sans-serif) !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) .slk-notice * {
        color: inherit !important;
        -webkit-text-fill-color: currentColor !important;
        border-color: transparent !important;
        background-color: transparent !important;
        text-shadow: none !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) .slk-notice :is(button, .close, [class*="close"]) {
        color: rgba(255, 255, 255, .6) !important;
        box-shadow: none !important;
    }
    /* 일반 알림은 누를 수 있다는 표시 */
    html:has(> body.slk-ui) #toast-container > div { cursor: pointer !important; }
}

/* 1.4.48: 페르소나 Connections 버튼(기본값/캐릭터/채팅) = 같은 너비로 한 줄 꽉, 아이콘·글자 겹침 수정
   (실제 ST에선 이 버튼들이 펼친 페르소나 카드 안에 있어 기존 규칙이 안 걸렸음) */
@media screen {
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #PersonaManagement #persona_connections_buttons {
        display: grid !important;
        grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
        gap: 8px !important;
        width: 100% !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #PersonaManagement #persona_connections_buttons > .menu_button {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        gap: 6px !important;
        justify-self: stretch !important;
        width: 100% !important;
        min-width: 0 !important;
        max-width: none !important;
        height: 40px !important;
        margin: 0 !important;
        padding: 0 6px !important;
        border: 1px solid #DDDDDD !important;
        border-radius: 10px !important;
        background: #FFFFFF !important;
        color: var(--slk-text, #1D1C1D) !important;
        box-shadow: none !important;
        filter: none !important;
        opacity: 1 !important;
        font-size: 14px !important;
        font-weight: 700 !important;
        white-space: nowrap !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #PersonaManagement #persona_connections_buttons > .menu_button.locked {
        border-color: var(--slk-aubergine, #4A154B) !important;
        background: var(--slk-aubergine, #4A154B) !important;
        color: #FFFFFF !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #PersonaManagement #persona_connections_buttons > .menu_button > i {
        position: static !important;
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        flex: 0 0 15px !important;
        width: 15px !important;
        min-width: 15px !important;
        height: 15px !important;
        margin: 0 !important;
        padding: 0 !important;
        transform: none !important;
        font-size: 0 !important;
        line-height: 1 !important;
        color: inherit !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #PersonaManagement #persona_connections_buttons > .menu_button > i::before {
        position: static !important;
        display: block !important;
        width: 15px !important;
        height: 15px !important;
        margin: 0 !important;
        background-color: currentColor !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #PersonaManagement #persona_connections_buttons > .menu_button > div {
        position: static !important;
        margin: 0 !important;
        padding: 0 !important;
        color: inherit !important;
        -webkit-text-fill-color: currentColor !important;
        white-space: nowrap !important;
    }
}

/* =====================================================================
   1.4.50 — 채팅 본문
   - 나레이션/대사 글자 크기 통일 (중간 크기 15px)
   - 대사("…") 글자 뒤에 연한 회색 배경
   - `…` 인라인 텍스트: 기호까지 보이게, 문자 메시지 말풍선 모양
   ===================================================================== */
@media screen {
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text {
        font-size: 15px !important;
        line-height: 1.6 !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text :is(p, q, em, i, strong, b, u, s, span, font, li, blockquote, div):not([class*="fa-"]) {
        font-size: inherit !important;
        line-height: inherit !important;
    }

    /* 대사 */
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text q {
        padding: 1px 3px !important;
        margin: 0 1px !important;
        border-radius: 4px !important;
        background: #EFEFEF !important;
        color: var(--slk-text, #1D1C1D) !important;
        -webkit-box-decoration-break: clone !important;
        box-decoration-break: clone !important;
    }
    

    /* `문자` 말풍선 */
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text :not(pre) > code {
        display: inline !important;
        visibility: visible !important;
        opacity: 1 !important;
        padding: 3px 10px !important;
        margin: 0 2px !important;
        border: 0 !important;
        border-radius: 14px 14px 14px 4px !important;
        background: #E9E9EB !important;
        color: var(--slk-text, #1D1C1D) !important;
        -webkit-text-fill-color: var(--slk-text, #1D1C1D) !important;
        font-family: var(--slk-font, sans-serif) !important;
        font-size: 14px !important;
        font-weight: 400 !important;
        line-height: 1.9 !important;
        text-shadow: none !important;
        white-space: pre-wrap !important;
        -webkit-box-decoration-break: clone !important;
        box-decoration-break: clone !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text :not(pre) > code::before,
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text :not(pre) > code::after {
        content: '`' !important;
        display: inline !important;
        color: #8B8B8B !important;
        -webkit-text-fill-color: #8B8B8B !important;
    }
    /* 내가 보낸 메시지 안의 `문자`는 파란 말풍선 */
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes[is_user="true"] .mes_text :not(pre) > code {
        border-radius: 14px 14px 4px 14px !important;
        background: #1264A3 !important;
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
    }
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes[is_user="true"] .mes_text :not(pre) > code::before,
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes[is_user="true"] .mes_text :not(pre) > code::after {
        color: rgba(255, 255, 255, .7) !important;
        -webkit-text-fill-color: rgba(255, 255, 255, .7) !important;
    }
    
}


/* =====================================================================
   1.4.51 — 받은 확장 설정 화면: 남아 있던 테마 색 제거 + 토글 스위치 보이게
   ===================================================================== */
@media screen {
    /* 테마 변수 자체를 슬랙 라이트 값으로 (확장 CSS가 이 변수를 많이 씀) */
    body.slk-ui:is(.slk-ui) {
        --SmartThemeBodyColor: #1D1C1D;
        --SmartThemeEmColor: #616061;
        --SmartThemeUnderlineColor: #1264A3;
        --SmartThemeBorderColor: #DDDDDD;
        --SmartThemeShadowColor: transparent;
        --SmartThemeBlurTintColor: rgba(255, 255, 255, .96);
        --SmartThemeChatTintColor: #FFFFFF;
        --SmartThemeUserMesBlurTintColor: #FFFFFF;
        --SmartThemeBotMesBlurTintColor: #FFFFFF;
        --SmartThemeCheckboxBgColorR: 255;
        --SmartThemeCheckboxBgColorG: 255;
        --SmartThemeCheckboxBgColorB: 255;
        --SmartThemeCheckboxBgColorA: 1;
        --SmartThemeCheckboxTickColor: #FFFFFF;
        --black30a: rgba(0, 0, 0, .06);
        --black50a: rgba(0, 0, 0, .10);
        --black70a: rgba(0, 0, 0, .14);
        --white20a: rgba(0, 0, 0, .04);
        --white30a: rgba(0, 0, 0, .06);
        --white50a: rgba(0, 0, 0, .10);
        --grey30a: rgba(0, 0, 0, .06);
    }

    /* 확장 설정 안의 굵은 검정 테두리 → 연회색 (확장 자체 스타일보다 우선, 우리 입력칸 규칙은 유지) */
    html body.slk-ui:not(#slk-a):not(#slk-b) #rm_extensions_block .inline-drawer-content:not(#slk-extension-settings-content) :where(*) {
