  html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes[data-slk-actions-flow] .mes_buttons {
    grid-column: 2 / -1 !important;
    grid-row: 1 / 3 !important;
    align-self: center !important;
    justify-self: stretch !important;
    margin: 0 !important;
    padding: 0 !important;
    min-width: 0 !important;
    height: auto !important;
    display: block !important;
  }
  html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes[data-slk-actions-flow] .mes_buttons > .extraMesButtons {
