/* ====================================================================
   v1.4.95 — chat-only solid upper header + three independent ink colors
   Keep purple navigation outside chats, and preserve user color choices.
   ==================================================================== */
@media screen {
    /* Keep the iPhone safe-area/status strip in the same chat canvas color. */
    html:has(> body.slk-ui.slk-in-chat:is(.slk-ui)) {
        background-color: #FFFFFF !important;
    }
    
    /* Restore the original floating-chat white fade instead of a hard white slab.
       Only active chats get this; settings drawers keep their normal header. */
    html body.slk-ui:not(#slk-a):not(#slk-b):not(#slk-c).slk-in-chat:not(.slk-panel-opening):not(:has(#top-settings-holder > .drawer .drawer-icon.openIcon)) #slk-header {
        background: linear-gradient(to bottom,
            rgba(255,255,255,.98) 0%,
            rgba(255,255,255,.85) 55%,
            rgba(255,255,255,0) 100%) !important;
        background-color: transparent !important;
        color: var(--slk-text) !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
    }
    
    /* Only set colors when explicitly selected; otherwise all existing
       existing typography remains untouched. */
    html body.slk-ui.slk-ink-narration:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text,
    html body.slk-ui.slk-ink-narration:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text :is(p, em, i:not([class*="fa-"]), strong, b, u, s, span, font, li, blockquote, div):not(q *):not(pre *):not(code *) {
        color: var(--slk-ink-narration) !important;
        -webkit-text-fill-color: var(--slk-ink-narration) !important;
    }
    /* Dialogue text has its own setting and takes precedence over narrative. */
    html body.slk-ui.slk-ink-dialogue:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text q,
    html body.slk-ui.slk-ink-dialogue:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text q * {
        color: var(--slk-ink-dialogue) !important;
        -webkit-text-fill-color: var(--slk-ink-dialogue) !important;
    }
    /* Asterisk-wrapped narration (*text*) is rendered as <em> by Markdown.
       Keep it separate from fenced code (<pre>) and quoted dialogue (<q>).
       The existing #999999 is the default/reset for this setting. */
    html body.slk-ui.slk-ink-ascii.slk-ink-ascii:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text em:not(q em):not(pre em):not(code em),
    html body.slk-ui.slk-ink-ascii.slk-ink-ascii:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text em:not(q em):not(pre em):not(code em) * {
        color: var(--slk-ink-ascii, #999999) !important;
        -webkit-text-fill-color: var(--slk-ink-ascii, #999999) !important;
    }
    /* Fenced / multiline code boxes have a fully independent ink color.
       Include highlighted spans; do not touch inline `code` bubbles. */
    html body.slk-ui.slk-ink-code:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text pre,
    html body.slk-ui.slk-ink-code:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text pre *,
    html body.slk-ui.slk-ink-code:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text .code-block,
    html body.slk-ui.slk-ink-code:not(#slk-a):not(#slk-b):not(#slk-c) #chat .mes_text .code-block * {
        color: var(--slk-ink-code) !important;
        -webkit-text-fill-color: var(--slk-ink-code) !important;
    }
}
